import { useQuery } from '@tanstack/react-query';
import { getJson } from '../../api/http';
import { sheetKey } from '../sheet/sheet';
import { type Claim, counts } from '../claims/claims';
import { type Grades, gradeOn } from '../people/people';

/** A grade's rate: `pct` is a percent with two decimals; `from` (yyyy-MM-dd) is the date it applies
 *  from, null for from the beginning of time. A grade may have several; one with no rate has none. */
export type Rate = { grade: string; pct: string; from: string | null };

/** Under the sheet's key, so loading the sheet again re-reads its rates. */
export const ratesKey = (sheet: string) => [...sheetKey(sheet), 'rates'] as const;

export function useRates(sheet: string) {
  return useQuery({
    queryKey: ratesKey(sheet),
    queryFn: () => getJson<Rate[]>(`/api/sheets/${encodeURIComponent(sheet)}/rates`),
    enabled: sheet !== '',
  });
}

/** The grade's percent in force on the date (yyyy-MM-dd): the rate with the latest from-date on or
 *  before it, or undefined when none of the grade's rates applies then. */
export function rateOf(rates: Rate[] | undefined, grade: string, on: string | undefined): string | undefined {
  if (on === undefined) return undefined;
  let best: Rate | undefined;
  for (const r of rates ?? []) {
    if (r.grade !== grade || (r.from !== null && r.from > on)) continue;
    if (best === undefined || (best.from ?? '') < (r.from ?? '')) best = r;
  }
  return best?.pct;
}

export const NA = 'n/a';

/** Whole hundredths of a two-decimal number, read exactly from its text. */
function hundredths(value: string): bigint {
  const [whole, frac = ''] = value.trim().replace(/^-/, '').split('.');
  const n = BigInt(whole || '0') * 100n + BigInt((frac + '00').slice(0, 2));
  return value.trim().startsWith('-') ? -n : n;
}

/** Hundredths as text with two decimals. */
function format(cents: bigint): string {
  const neg = cents < 0n;
  const abs = neg ? -cents : cents;
  return `${neg ? '-' : ''}${abs / 100n}.${String(abs % 100n).padStart(2, '0')}`;
}

/** amount × pct ÷ 100, rounded half to even to two decimals; n/a when there is no rate. */
export function due(amount: string, pct: string | undefined): string {
  if (pct === undefined) return NA;
  // amount (hundredths) × pct (hundredths) is in units of 1/10000 cent-percent: ÷ 10000 gives cents.
  const product = hundredths(amount) * hundredths(pct);
  const abs = product < 0n ? -product : product;
  const rest = abs % 10000n;
  let cents = abs / 10000n;
  if (rest > 5000n || (rest === 5000n && cents % 2n === 1n)) cents += 1n;
  return format(product < 0n ? -cents : cents);
}

/** A live due: amount at pct (see `due`), raised to the sheet's floor (two decimals) when below it;
 *  n/a when there is no rate. */
export function liveDue(amount: string, pct: string | undefined, floor: string | undefined): string {
  const d = due(amount, pct);
  if (d === NA || floor === undefined || hundredths(d) >= hundredths(floor)) return d;
  return format(hundredths(floor));
}

/** The sum of these dues, skipping n/a; two decimals. */
export function dueTotal(dues: string[]): string {
  return format(dues.filter((d) => d !== NA).reduce((sum, d) => sum + hundredths(d), 0n));
}

/** What a claim's late charge follows: the sheet's late percent (two decimals) and how many full
 *  30 days the claim is overdue. */
export type Late = { pct: string | undefined; periods: (claim: Claim) => number };

/** The late charge on a figure: the late percent of it for every full 30 days overdue, rounded like due. */
function lateCharge(claim: Claim, figure: string, late: Late | undefined): string | undefined {
  const periods = late?.pct === undefined ? 0 : late.periods(claim);
  if (periods <= 0 || figure === NA) return undefined;
  return due(figure, format(hundredths(late!.pct!) * BigInt(periods)));
}

/** Whether the claim keeps a figure whatever the rates: fixed when settled, or bound by a statement. */
const fixed = (claim: Claim) => claim.due !== null || (claim.stated && claim.statedDue !== null);

/** A claim's due: the due fixed when it was settled (its late charge frozen in), else its figure — the
 *  figure its person's last statement bound it to, else its live due: its amount at the rate in force
 *  on the claim's date of its person's grade in force on that date, at least the sheet's floor — plus its late charge when overdue.
 *  A statement never binds the charge: it keeps following the sheet's today. */
export function claimDue(
  claim: Claim,
  rates: Rate[] | undefined,
  grades: Grades,
  floor: string | undefined,
  late?: Late,
): string {
  if (claim.due !== null) return claim.due;
  const figure = (claim.stated ? claim.statedDue : null) ?? liveDue(claim.amount, rateOf(rates, gradeOn(grades, claim.date), claim.date), floor);
  const charge = lateCharge(claim, figure, late);
  return charge === undefined ? figure : format(hundredths(figure) + hundredths(charge));
}

/** A person's due-total: the sum of the figures of their claims that count. n/a when their grade
 *  in force on the sheet's today has no rate then, unless a claim that counts keeps a fixed (settled or
 *  stated) figure, or a figure at another grade (the one in force on its date). */
export function personDue(
  claims: Claim[],
  rates: Rate[] | undefined,
  grades: Grades,
  today: string | undefined,
  floor: string | undefined,
  late?: Late,
): string {
  const mine = claims.filter(counts);
  const now = gradeOn(grades, today);
  const elsewhere = (c: Claim) => gradeOn(grades, c.date) !== now && rateOf(rates, gradeOn(grades, c.date), c.date) !== undefined;
  if (rateOf(rates, now, today) === undefined && !mine.some((c) => fixed(c) || elsewhere(c))) {
    return NA;
  }
  return dueTotal(mine.map((c) => claimDue(c, rates, grades, floor, late)));
}
import type { Claim } from '../claims/claims';
import { type Late, type Rate, claimDue, dueTotal } from '../rates/rates';
import type { Settings } from '../settings/settings';
import type { Grades } from '../people/people';

/** The terms a sheet has until they are set: 14 days. */
export const DEFAULT_TERMS = '14';

/** The claim's due-by (yyyy-MM-dd): its date plus the terms (whole days) in force. */
export function dueBy(claim: Claim, terms: string | undefined): string {
  const d = new Date(`${claim.date}T00:00:00Z`);
  d.setUTCDate(d.getUTCDate() + Number(terms ?? DEFAULT_TERMS));
  return d.toISOString().slice(0, 10);
}

/** Whether the claim is overdue: it is OPEN and its due-by is before the sheet's today. */
export function overdue(claim: Claim, terms: string | undefined, today: string | undefined): boolean {
  return claim.status === 'OPEN' && today !== undefined && dueBy(claim, terms) < today;
}

const DAY = 24 * 60 * 60 * 1000;

/** How many full 30 days the claim is overdue on the sheet's today (0 when it is not overdue). */
export function latePeriods(claim: Claim, terms: string | undefined, today: string | undefined): number {
  if (today === undefined || !overdue(claim, terms, today)) return 0;
  const days = (Date.parse(`${today}T00:00:00Z`) - Date.parse(`${dueBy(claim, terms)}T00:00:00Z`)) / DAY;
  return Math.floor(days / 30);
}

/** What the sheet's late charge follows: its late percent, its terms and its today. */
export function lateOf(settings: Settings | undefined, today: string | undefined): Late {
  return { pct: settings?.latePct, periods: (c) => latePeriods(c, settings?.terms, today) };
}

/** A person's overdue claims among these (their claims that count): how many, and the sum of their
 *  dues (late charge included) at the person's grade in force on each claim's date, skipping n/a. */
export function overdueFigures(
  claims: Claim[],
  rates: Rate[] | undefined,
  grades: Grades,
  floor: string | undefined,
  terms: string | undefined,
  today: string | undefined,
  lateCharge?: Late,
): { count: number; total: string } {
  const late = claims.filter((c) => overdue(c, terms, today));
  return { count: late.length, total: dueTotal(late.map((c) => claimDue(c, rates, grades, floor, lateCharge))) };
}

